def _pointnav_loop_escape_candidate_refs(
    vlm_input: Mapping[str, object],
    *,
    maximum_bearing_error_deg: float = 45.0,
) -> tuple[str | None, float | None, tuple[str, ...]]:
    """Bind an active deadlock escape to RGB-verified frontier waypoints."""

    if (
        not math.isfinite(float(maximum_bearing_error_deg))
        or not 0.0 < float(maximum_bearing_error_deg) <= 90.0
    ):
        raise VlmRuntimeError("INVALID_POINTNAV_LOOP_ESCAPE_BEARING_ERROR")
    memory = vlm_input.get("memory")
    if not isinstance(memory, Mapping):
        return None, None, ()
    goal_context = memory.get("goal_context")
    if (
        not isinstance(goal_context, Mapping)
        or str(goal_context.get("supervisor_mode") or "").strip().lower()
        != "escape_deadlock"
    ):
        return None, None, ()
    loop_warning = memory.get("loop_warning")
    if (
        not isinstance(loop_warning, Mapping)
        or loop_warning.get("is_looping") is not True
    ):
        return None, None, ()
    local_topology = memory.get("local_topology")
    raw_exits = (
        local_topology.get("candidate_exits")
        if isinstance(local_topology, Mapping)
        else None
    )
    if not isinstance(raw_exits, list):
        return None, None, ()
    exits: list[tuple[float, str, float, str]] = []
    for exit_candidate in raw_exits:
        if (
            not isinstance(exit_candidate, Mapping)
            or exit_candidate.get("avoid") is not False
        ):
            continue
        candidate_ref = exit_candidate.get("candidate_ref")
        bearing_deg = _finite_metric(exit_candidate.get("bearing_deg_robot"))
        score = _finite_metric(exit_candidate.get("score"))
        if (
            not isinstance(candidate_ref, str)
            or not candidate_ref
            or bearing_deg is None
        ):
            continue
        exits.append(
            (
                -(score if score is not None else -float("inf")),
                candidate_ref,
                bearing_deg,
                str(exit_candidate.get("status") or "").strip().lower(),
            )
        )
    if not exits:
        return None, None, ()
    candidate_block = vlm_input.get("pixel_candidates")
    raw_candidates = (
        candidate_block.get("candidates")
        if isinstance(candidate_block, Mapping)
        else None
    )
    if not isinstance(raw_candidates, list):
        return None, None, ()
    candidates: list[tuple[str, float, float]] = []
    for candidate in raw_candidates:
        if (
            not isinstance(candidate, Mapping)
            or candidate.get("avoid") is not False
            or candidate.get("executable") is not True
        ):
            continue
        candidate_ref = candidate.get("candidate_ref")
        candidate_bearing_deg = _finite_metric(candidate.get("bearing_deg_robot"))
        if (
            not isinstance(candidate_ref, str)
            or not candidate_ref
            or candidate_bearing_deg is None
        ):
            continue
        distance_m = _finite_metric(candidate.get("distance_m"))
        candidates.append(
            (
                candidate_ref,
                candidate_bearing_deg,
                distance_m if distance_m is not None else 0.0,
            )
        )
    viable_exits: list[
        tuple[int, float, str, float, list[tuple[float, float, str]]]
    ] = []
    for negative_score, exit_ref, exit_bearing_deg, status in exits:
        matches: list[tuple[float, float, str]] = []
        for candidate_ref, candidate_bearing_deg, distance_m in candidates:
            bearing_error_deg = abs(
                _heading_delta_deg(candidate_bearing_deg, exit_bearing_deg)
            )
            if bearing_error_deg > float(maximum_bearing_error_deg):
                continue
            matches.append((bearing_error_deg, -distance_m, candidate_ref))
        if matches:
            matches.sort()
            viable_exits.append(
                (
                    0 if status == "unknown_frontier" else 1,
                    negative_score,
                    exit_ref,
                    exit_bearing_deg,
                    matches,
                )
            )
    if not viable_exits:
        return None, None, ()
    _known_rank, _negative_score, exit_ref, exit_bearing_deg, matches = min(
        viable_exits,
        key=lambda entry: (entry[0], entry[1], entry[2]),
    )
    return exit_ref, exit_bearing_deg, tuple(entry[2] for entry in matches)

